/* =====================================================================================================
   MANUAL SQL UPGRADE SCRIPT
   Migration: 202609090647151_AgentCostUserCredits
   Predecessor: 202609090519337_AgentCostTables
   =====================================================================================================
   For operators / DBAs who upgrade the Analytics database schema BY HAND instead of running the installer
   (which applies EF migrations automatically). It performs the same schema change as the migration and
   then stamps __MigrationHistory so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion) and the web
   app Health page recognise it as applied.

   WHAT IT DOES
     Creates one NEW, EMPTY table:

       * copilot_studio_credit_user_daily   billed Copilot Studio credits attributed to an individual
                                            user, per day

     This is the per-USER view of Copilot Studio spend. It comes from the Power Platform licensing API's
     per-user entitlement routes, which Microsoft added in July 2026 - a different endpoint from the
     per-agent one that fills copilot_studio_credit_daily, not a breakdown of it. The two tables are
     populated independently and their totals are not guaranteed to reconcile exactly.

     The user is linked to dbo.users by a real FOREIGN KEY. The licensing API reports the user as an
     Entra object id, which is the same value the user import already stores in dbo.users.azure_ad_id
     (it maps it from Graph's user.id), so the join needs no new column and no backfill. The raw
     identifier is kept alongside the key in entra_object_id.

     The key is NULLABLE and does NOT cascade on delete. Nullable because a billing row must survive a
     user who cannot be resolved - someone deleted from the directory, or created since the last user
     import - and the importer re-attempts those rows on later cycles. Non-cascading because deleting a
     user must never silently erase spend history and change historical totals.

   CLASSIFICATION: PURELY ADDITIVE
     Nothing existing is altered, dropped or rewritten. No existing table is touched, no existing column
     changes type, and no existing query changes plan - so there is no "before" state to measure and this
     migration carries no performance benchmark by design. The foreign key points AT dbo.users but adds
     no column to it and does not validate any existing row, because the referencing table is new and
     empty.

   HOW LONG IT TAKES / DOWNTIME
     Seconds, on a tenant of any size. NO MAINTENANCE WINDOW IS NEEDED and the importer does not have to
     be stopped.

   ABOUT THE UNIQUE INDEX
     It is the upsert key, not an optimisation. Copilot Studio recalculates consumption as usage days
     settle, so the importer deliberately re-reads a trailing window on every run; without this index a
     re-read would duplicate every restated day instead of correcting it.

   AFTER RUNNING THIS
     The table stays empty until the "Copilot Studio credits" import is switched on in the installer AND
     the runtime service principal holds a Power Platform RBAC role. It will also stay empty if this
     tenant's licensing API does not expose the per-user routes - in that case the importer logs that the
     route is unavailable and the per-agent figures continue to import normally. Check
     dbo.agent_cost_import_log for the 'CopilotStudioUserCredits' rows.

   IDEMPOTENT
     Every step is guarded, so running this script twice is safe and the second run is a no-op.

   RUN ORDER
     The manual scripts form a strict prerequisite chain. Run them in migration-id order. This script
     requires 202609090519337_AgentCostTables to be stamped first and will refuse to
     stamp itself (with an error) if it is not.
   ===================================================================================================== */

SET NOCOUNT ON;

/* QUOTED_IDENTIFIER must be ON for the xs:base64Binary() call that rebuilds the model blob further
   down. SSMS connects with it ON, but sqlcmd defaults it OFF, so without this the stamp fails with
   "INSERT failed because the following SET options have incorrect settings: 'QUOTED_IDENTIFIER'" -
   after the schema work has already succeeded, leaving the migration unstamped and blocking the next
   script in the chain. */
SET QUOTED_IDENTIFIER ON;
GO

/* =====================================================================================================
   PRE-FLIGHT - runs BEFORE anything is created. See the note in
   202609090519337_AgentCostTables.manual.sql: a severity-16 RAISERROR does not stop sqlcmd, so without
   SET NOEXEC ON an out-of-order run would create this migration's schema and leave it unstamped, and the
   next installer run would then fail inside EF's own CreateTable. SET NOEXEC OFF at the end of the
   script restores the session.
   ===================================================================================================== */
IF OBJECT_ID(N'dbo.__MigrationHistory', N'U') IS NULL
BEGIN
    RAISERROR('AgentCostUserCredits: dbo.__MigrationHistory does not exist - this does not look like an Analytics database. Nothing has been changed.', 16, 1) WITH NOWAIT;
    SET NOEXEC ON;
END

IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609090519337_AgentCostTables')
   AND NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609090647151_AgentCostUserCredits')
BEGIN
    RAISERROR('AgentCostUserCredits: prerequisite migration 202609090519337_AgentCostTables is not stamped in __MigrationHistory. Run the manual scripts in migration-id order. Nothing has been changed.', 16, 1) WITH NOWAIT;
    SET NOEXEC ON;
END
GO

DECLARE @migration nvarchar(200) = N'202609090647151_AgentCostUserCredits';
DECLARE @msg nvarchar(500);

SET @msg = @migration + N': starting.';
RAISERROR(@msg, 0, 1) WITH NOWAIT;

/* ---------------------------------------------------------------------------------------------------
   dbo.copilot_studio_credit_user_daily

   Every text column is nvarchar: user identifiers and environment names come from a customer tenant and
   can contain non-Latin characters, which varchar would silently corrupt.
   --------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_user_daily', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.copilot_studio_credit_user_daily (
        [id]               int             IDENTITY(1, 1) NOT NULL,
        [usage_date]       datetime        NOT NULL,
        [entra_object_id]  nvarchar(200)   NULL,
        [user_id]          int             NULL,
        [environment_id]   nvarchar(200)   NULL,
        [environment_name] nvarchar(255)   NULL,
        [agent_id]         nvarchar(200)   NULL,
        [billed_credits]   decimal(18, 6)  NOT NULL,
        [unit]             nvarchar(50)    NULL,
        [dimension_hash]   nvarchar(64)    NOT NULL,
        [imported_utc]     datetime        NOT NULL,
        CONSTRAINT [PK_dbo.copilot_studio_credit_user_daily] PRIMARY KEY CLUSTERED ([id] ASC)
    );
    RAISERROR('AgentCostUserCredits: created dbo.copilot_studio_credit_user_daily.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AgentCostUserCredits: dbo.copilot_studio_credit_user_daily already exists.', 0, 1) WITH NOWAIT;
GO

IF OBJECT_ID(N'dbo.copilot_studio_credit_user_daily', N'U') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.indexes
                   WHERE object_id = OBJECT_ID(N'dbo.copilot_studio_credit_user_daily')
                     AND name = N'IX_usage_date_dimension_hash')
BEGIN
    CREATE UNIQUE INDEX [IX_usage_date_dimension_hash]
        ON dbo.copilot_studio_credit_user_daily ([usage_date] ASC, [dimension_hash] ASC);
    RAISERROR('AgentCostUserCredits: created IX_usage_date_dimension_hash.', 0, 1) WITH NOWAIT;
END
GO

/* ---------------------------------------------------------------------------------------------------
   The foreign-key index and the entra_object_id index.

   IX_user_id is what EF would create for the relationship; without it, deleting or updating a user has
   to scan this table. IX_entra_object_id serves the importer's re-attribution pass, which looks for
   rows whose user could not be resolved when they were first stored.
   --------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_user_daily', N'U') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.indexes
                   WHERE object_id = OBJECT_ID(N'dbo.copilot_studio_credit_user_daily')
                     AND name = N'IX_user_id')
BEGIN
    CREATE INDEX [IX_user_id] ON dbo.copilot_studio_credit_user_daily ([user_id] ASC);
    RAISERROR('AgentCostUserCredits: created IX_user_id.', 0, 1) WITH NOWAIT;
END
GO

IF OBJECT_ID(N'dbo.copilot_studio_credit_user_daily', N'U') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.indexes
                   WHERE object_id = OBJECT_ID(N'dbo.copilot_studio_credit_user_daily')
                     AND name = N'IX_entra_object_id')
BEGIN
    CREATE INDEX [IX_entra_object_id] ON dbo.copilot_studio_credit_user_daily ([entra_object_id] ASC);
    RAISERROR('AgentCostUserCredits: created IX_entra_object_id.', 0, 1) WITH NOWAIT;
END
GO

/* ---------------------------------------------------------------------------------------------------
   The foreign key itself. Instant: the referencing table is new and empty, so there is nothing for SQL
   Server to validate. NO ACTION on delete is deliberate - see the header.
   --------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_user_daily', N'U') IS NOT NULL
   AND OBJECT_ID(N'dbo.users', N'U') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.foreign_keys
                   WHERE name = N'FK_dbo.copilot_studio_credit_user_daily_dbo.users_user_id')
BEGIN
    ALTER TABLE dbo.copilot_studio_credit_user_daily
        ADD CONSTRAINT [FK_dbo.copilot_studio_credit_user_daily_dbo.users_user_id]
        FOREIGN KEY ([user_id]) REFERENCES dbo.users ([id]);
    RAISERROR('AgentCostUserCredits: created the foreign key to dbo.users.', 0, 1) WITH NOWAIT;
END
GO

/* =====================================================================================================
   Record the migration so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion) and the web app Health
   page treat it as applied.

   This migration CHANGES THE EF ENTITY MODEL (it adds an entity), so its model snapshot is NOT identical
   to its predecessor's and the stamp cannot simply copy that row. The new snapshot is embedded below as
   base64 and converted to the varbinary blob EF stores.

   The pre-stamp guard checks SCHEMA ONLY - that the table exists. It deliberately does not inspect any
   row counts: a data-state guard cannot be satisfied reliably while the importer is running, and
   refusing to stamp on that basis has previously stranded a customer upgrade by blocking the next script
   in the chain.
   ===================================================================================================== */
IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609090647151_AgentCostUserCredits')
BEGIN
    IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609090519337_AgentCostTables')
        RAISERROR('AgentCostUserCredits: prerequisite migration 202609090519337_AgentCostTables is missing from __MigrationHistory, so this was NOT stamped. Run the manual scripts in migration-id order.', 16, 1) WITH NOWAIT;
    ELSE IF OBJECT_ID(N'dbo.copilot_studio_credit_user_daily', N'U') IS NULL
        RAISERROR('AgentCostUserCredits: NOT stamped - the schema work did not complete (the table is missing). Re-run this script; note that sqlcmd and SSMS continue past a failed batch, so an earlier error may be further up the output.', 16, 1) WITH NOWAIT;
    ELSE IF NOT EXISTS (SELECT 1 FROM sys.columns
                        WHERE object_id = OBJECT_ID(N'dbo.copilot_studio_credit_user_daily')
                          AND name = N'entra_object_id')
        RAISERROR('AgentCostUserCredits: NOT stamped - the schema work did not complete (entra_object_id is missing). Re-run this script; note that sqlcmd and SSMS continue past a failed batch, so an earlier error may be further up the output.', 16, 1) WITH NOWAIT;
    ELSE IF NOT EXISTS (SELECT 1 FROM sys.foreign_keys
                        WHERE name = N'FK_dbo.copilot_studio_credit_user_daily_dbo.users_user_id')
        RAISERROR('AgentCostUserCredits: NOT stamped - the schema work did not complete (the foreign key to dbo.users is missing). Re-run this script; note that sqlcmd and SSMS continue past a failed batch, so an earlier error may be further up the output.', 16, 1) WITH NOWAIT;
    ELSE
    BEGIN
        DECLARE @model nvarchar(max) = N'';

        INSERT INTO dbo.__MigrationHistory (MigrationId, ContextKey, Model, ProductVersion)
        SELECT TOP 1
            N'202609090647151_AgentCostUserCredits',
            ContextKey,
            CAST(N'' AS xml).value('xs:base64Binary(sql:variable("@model"))', 'varbinary(max)'),
            ProductVersion
        FROM dbo.__MigrationHistory
        WHERE MigrationId = N'202609090519337_AgentCostTables';

        RAISERROR('AgentCostUserCredits: recorded in __MigrationHistory.', 0, 1) WITH NOWAIT;
    END
END
ELSE
    RAISERROR('AgentCostUserCredits: already recorded in __MigrationHistory, nothing to do.', 0, 1) WITH NOWAIT;
GO

-- Restore the session. SET statements still execute under NOEXEC, so this is reached even when the
-- pre-flight above turned NOEXEC on and skipped everything in between.
SET NOEXEC OFF;
GO